// Stage 3 - Story Director, per chapter: scenes -> ordered objectives (F04 SS2). Objectives are
// short open phrases (<= 6 words, enforced here AND by prompt), with hidden descriptions and
// structured completion predicates (SS4).

import { Check, countWords, extractJsonObject, looksCutOff } from '../json.ts'
import { validatePredicate } from '../predicates.ts'
import type { ChapterSketch, MetaLoop, ObjectiveDraft, ParseResult, SceneSketch } from '../types.ts'

export interface Stage3Context {
  metaLoop: MetaLoop
  chapter: ChapterSketch
  chapterNumber: number
  scenes: SceneSketch[]
  /** 'one_shot' keeps the objective ladder short; longer forms may use the full range. */
  adventureType?: string
  /** Titles already authored for earlier chapters - stage 3 runs per chapter and would
   *  otherwise re-author the same objective ("Secure the forged deed" twice, live 2026-07-20). */
  priorObjectiveTitles?: string[]
  /** Chapters in the adventure, so the remaining total can be shared out sensibly. */
  chapterCount?: number
}

export const OBJECTIVE_TITLE_MAX_WORDS = 6
export const OBJECTIVES_PER_CHAPTER = { min: 1, max: 6 }
/**
 * Per chapter of a multi-chapter adventure. The open 1-6 range let a 4-chapter mystery author
 * 16 objectives for a solo level-1 party (live 2026-07-20) - at the observed rate of roughly
 * one objective per 26 turns that is a ~400-turn story nobody finishes.
 */
export const MULTI_CHAPTER_OBJECTIVES = { min: 2, max: 4 }
/**
 * The cap that actually binds. Capping per chapter still allowed 4 x 4 = 16 across a
 * multi-chapter guide (observed 15), because the driver is chapter count, not chapter size.
 * Later chapters get whatever of this total is left.
 */
export const MULTI_CHAPTER_TOTAL_OBJECTIVES = 10
/** A one-shot is a whole story in one chapter, so its ladder must carry all three acts. */
export const ONE_SHOT_OBJECTIVES = { min: 3, max: 4 }

/**
 * One-shots used to be told "AT MOST 2-3 objectives", which authored Act 1 and stopped: both
 * objectives were setup, and the endings then demanded proof nothing in the ladder could
 * produce. The ladder now has to reach a climax, authored against the promised endings.
 */
function oneShotArcRules(ctx: Stage3Context): string {
  const premises = (ctx.metaLoop.endingPremises ?? []).filter(Boolean)
  return `- This is a ONE-SHOT adventure: author ${ONE_SHOT_OBJECTIVES.min}-${ONE_SHOT_OBJECTIVES.max} objectives forming a complete three-act spine - setup, escalation/complication, then a CLIMAX.
- The LAST objective is the climax: a confrontation or decisive act that resolves the story, not more investigation or setup. Its completion is what earns an ending.
${premises.length > 0 ? `- The climax objective must make one of these promised endings reachable: ${premises.join(' | ')}.\n` : ''}`
}

/**
 * Multi-chapter chapters share ONE ladder budget. Live play completes roughly one objective per
 * 26 turns, so a 15-16 rung ladder is a story nobody reaches the end of.
 */
const FINAL_CHAPTER_RULE =
  '- This is the FINAL chapter: its last objective is the climax, the decisive act that earns ' +
  'an ending.\n'

function multiChapterArcRules(ctx: Stage3Context): string {
  const used = (ctx.priorObjectiveTitles ?? []).length
  const chapters = Math.max(ctx.chapterCount ?? 1, 1)
  const remainingChapters = Math.max(chapters - (ctx.chapterNumber - 1), 1)
  const remaining = Math.max(MULTI_CHAPTER_TOTAL_OBJECTIVES - used, MULTI_CHAPTER_OBJECTIVES.min)
  // Leave room for the chapters after this one; the last chapter may spend what is left.
  const fairShare = Math.max(Math.floor(remaining / remainingChapters), MULTI_CHAPTER_OBJECTIVES.min)
  const max = Math.min(fairShare, MULTI_CHAPTER_OBJECTIVES.max, remaining)
  return `- Author ${MULTI_CHAPTER_OBJECTIVES.min}-${max} objectives for THIS chapter - each a distinct step the party must actually finish, not a restatement of a neighbouring step. The whole adventure gets at most ${MULTI_CHAPTER_TOTAL_OBJECTIVES} objectives across all ${chapters} chapters and ${used} are already authored, so spend this chapter's share and no more.
${ctx.chapterNumber >= chapters ? FINAL_CHAPTER_RULE : ''}`
}

export function buildStage3Prompt(ctx: Stage3Context): { system: string; user: string; maxTokens: number } {
  const system = `You are the Story Director for a tabletop RPG platform. Turn a chapter's scene sketches into an ORDERED list of ${OBJECTIVES_PER_CHAPTER.min}-${OBJECTIVES_PER_CHAPTER.max} player-facing objectives.

Rules:
- Objective titles are AT MOST ${OBJECTIVE_TITLE_MAX_WORDS} words, phrased short and OPEN ("Defeat Volgarth", "Find the missing caravan") - they must not prescribe a method.
- The title is the ONE field here the PLAYER reads. It appears in their quest journal the moment the objective is revealed, before they have played any of it, and again when it completes. It must therefore contain NOTHING the party has not already learned by then. Name what the party INTENDS to do, never what the world turns out to be: "Stop what comes at dawn", not "Confront the Dawn Collection" - the second one hands them the twist in the journal. Everything you know from the meta loop is fair game for hidden_description and for nothing else.
- hidden_description is DM-only: what this objective is really about and what the party does not yet know. It exists to catch plot holes. Write COMPLETE prose ending on a finished sentence - a description cut off mid-word ships a broken guide.
- Describe the OUTCOME, never the ROUTE. The playable scenes do not exist yet - they are authored two stages after you, from these sketches, and a party may achieve this objective by a way you cannot see from here. So write what the party will KNOW or HOLD once it is done ("armed with the truth of the keeper's error"), never how they came by it ("learned from Mara, or from the bones on the shelf"). Naming a method here commits every later objective to a route that may never be played: if the party takes another way, the rest of the adventure is written for a party that learned something they never learned.
- completion_predicates names what ACHIEVING this objective looks like in world state. It does not decide when the objective is done - the scenes authored later do that - so it is a description, not a contract. It is used to flavour the world once the party wins. Grammar:
  atom: {"flag": "<snake_case_milestone>", "eq": true} - a concrete accomplishment ("lantern_relit", "keeper_freed"). PREFER flags.
  atom: {"event": "<short past-tense marker>"} - e.g. "party entered the sunken crypt", "the ritual was interrupted".
  combinators: {"any": [<predicate>...]}, {"all": [<predicate>...]}
- The cast is NOT named yet - NPCs are authored after you. So never invent placeholder identities to stand in for them ("claimant_a_arrived", "guard_b_bribed"): at play time an observer sees "Lady Isolde arrived" and has no way to know which letter she was. Write each atom as something the PARTY accomplished, recognisable from the scene alone ("all_claimants_received", "passage_secured").
- Keep it SHORT - one or two atoms. Prefer "any" over "all".
- Every objective must require NEW play the party has not already done when it becomes their goal. NEVER author a rung the opening setup ALREADY satisfies - most often a "find/meet/reach" step aimed at an NPC or place the party is already with as the chapter begins. The quest-giver who hands them this quest is already found; "locate them" completes the instant it is revealed, flashes up and vanishes "for no reason", and the ladder telescopes to whatever comes next. Each rung is an obstacle still ahead of them, not a restatement of where they start.

${ctx.adventureType === 'one_shot'
  ? oneShotArcRules(ctx)
  : multiChapterArcRules(ctx)}${
  (ctx.priorObjectiveTitles ?? []).length > 0
    ? `- Earlier chapters already cover these - do NOT repeat or re-word any of them: ${(ctx.priorObjectiveTitles ?? []).join(' | ')}.
`
    : ''}
- "kind" is "main" or "side". MAIN is a PLOT POINT: something the story requires to happen, shown to the player so they know where they are in it. The party cannot fail a main objective - however their scenes go, it becomes true, and how it went changes only the flavour, the price and which ending they steer toward. SIDE is an optional thread that can genuinely be lost, where losing it changes nothing later depends on. Default to "main". Author a "side" objective ONLY when the adventure reads exactly the same without it - if any later objective assumes it happened, it is main. The LAST objective is the climax and is always "main".

Respond with ONLY a JSON object, no prose, in exactly this shape:
{ "objectives": [ { "title": "...", "kind": "main", "hidden_description": "...", "completion_predicates": { ... } } ] }`

  const sceneList = ctx.scenes.map((s, i) => `Scene ${i + 1}: ${s.sketch}`).join('\n')
  // Stage 1's entity registry, which this prompt used to withhold. Without it the only way to
  // write a milestone about a person was to invent a placeholder for them ("claimant_a_arrived"),
  // and at play time an observer who sees "Lady Isolde arrived" cannot tell which letter she was,
  // so the objective never completes. The names exist before this stage runs - pass them on.
  const cast = (ctx.metaLoop.entities ?? [])
    .map((e) => `- ${e.name} (${e.kind}): ${e.note}`)
    .join('\n')
  const user = `Meta loop antagonist: ${ctx.metaLoop.antagonist}
Stakes: ${ctx.metaLoop.stakes}
${cast ? `
Named cast and places already fixed by the story spine - milestone atoms about any of them MUST use these exact names, never a placeholder:
${cast}
` : ''}
Chapter ${ctx.chapterNumber}: ${ctx.chapter.title}
Arc summary: ${ctx.chapter.arcSummary}

Scene sketches:
${sceneList}`

  return { system, user, maxTokens: 3000 }
}

export function containsFactAtom(predicate: unknown): boolean {
  if (typeof predicate !== 'object' || predicate === null || Array.isArray(predicate)) return false
  const p = predicate as Record<string, unknown>
  if (typeof p.fact === 'string') return true
  if (Array.isArray(p.any)) return p.any.some(containsFactAtom)
  if (Array.isArray(p.all)) return p.all.some(containsFactAtom)
  return false
}

/**
 * True when the predicate holds at least one atom live play can actually claim - a {flag, eq:true}
 * or an {event}. This mirrors listMilestoneAtoms' flag/event vocabulary (story/evaluate) WITHOUT
 * importing it: story/evaluate already imports guide/predicates, so the reverse edge would cycle.
 * Fact atoms are omitted deliberately - they are hard-failed one branch up, so a predicate that
 * reaches the zero-claimable check never contains one.
 */
export function hasClaimableAtom(predicate: unknown): boolean {
  if (typeof predicate !== 'object' || predicate === null || Array.isArray(predicate)) return false
  const p = predicate as Record<string, unknown>
  if (Array.isArray(p.any)) return p.any.some(hasClaimableAtom)
  if (Array.isArray(p.all)) return p.all.some(hasClaimableAtom)
  if (typeof p.flag === 'string' && p.flag && p.eq === true) return true
  return typeof p.event === 'string' && p.event.length > 0
}

export function parseStage3(raw: string): ParseResult<ObjectiveDraft[]> {
  const extracted = extractJsonObject(raw)
  if (!extracted.ok) return extracted

  const c = new Check()
  const objectives = c
    .arr(extracted.data.objectives, '$.objectives', OBJECTIVES_PER_CHAPTER.min, OBJECTIVES_PER_CHAPTER.max)
    .map((raw, i) => {
      const path = `$.objectives[${i}]`
      const o = c.obj(raw, path)
      const title = c.str(o.title, `${path}.title`)
      if (title && countWords(title) > OBJECTIVE_TITLE_MAX_WORDS) {
        c.errors.push(`${path}.title: "${title}" is over ${OBJECTIVE_TITLE_MAX_WORDS} words`)
      }
      // Shape only (2026-07-27). Two hard errors used to live here - "fact atoms are not
      // completable by live play" and "has no claimable milestone" - and both said the same thing:
      // this predicate can never complete the objective, so regenerate the whole chapter. That
      // was true when the predicate WAS completion. Objectives now resolve because a scene
      // resolved, so an unclaimable predicate costs exactly one flavour flag nobody sets, and
      // failing a paid generation over it is a worse outcome than shipping it.
      c.errors.push(...validatePredicate(o.completion_predicates, `${path}.completion_predicates`))
      const hiddenDescription = c.str(o.hidden_description, `${path}.hidden_description`)
      if (hiddenDescription && looksCutOff(hiddenDescription)) {
        // "Success here means the pa" shipped live (2026-07-22) and surfaced only as a stage-7
        // residue warning a human had to read. Form check, bound here at the author.
        c.errors.push(`${path}.hidden_description: ends mid-thought ("...${hiddenDescription.slice(-30)}") - finish the sentence`)
      }
      // main vs side (2026-07-29). A main objective is a PLOT POINT - it becomes true however its
      // routes went and can never be failed; a side objective is an optional thread that can be
      // lost, where losing only colours the story. Absent reads as `main`, which is the safe
      // direction: a side thread wrongly marked main costs a losable thread, while a plot point
      // wrongly marked side lets the spine lose a fact later objectives assume.
      const kind = c.oneOf(o.kind ?? 'main', `${path}.kind`, ['main', 'side'] as const)
      return {
        title,
        hiddenDescription,
        completionPredicates: (o.completion_predicates ?? null) as ObjectiveDraft['completionPredicates'],
        kind: (kind ?? 'main') as ObjectiveDraft['kind'],
      }
    })

  // The ladder must be a spine, not a pile of optional threads. The climax in particular is what
  // earns an ending, so it can never be the objective the party is allowed to lose.
  if (objectives.length > 0 && objectives[objectives.length - 1].kind !== 'main') {
    c.errors.push('$.objectives: the LAST objective is the climax and must be kind "main"')
  }
  if (objectives.length > 0 && !objectives.some((o) => o.kind === 'main')) {
    c.errors.push('$.objectives: at least one objective must be kind "main" - the chapter needs a spine')
  }

  const seen = new Set<string>()
  for (const objective of objectives) {
    const key = objective.title.trim().toLowerCase()
    if (!key) continue
    if (seen.has(key)) c.errors.push(`$.objectives: duplicate objective title "${objective.title}"`)
    seen.add(key)
  }

  return c.result(objectives)
}
